mapper.select:
SELECT * FROM artifact
WHERE tenant_id = #{tenantId} AND workitem_id = #{workitemId}
ORDER BY id DESC

SELECT * FROM artifact
WHERE tenant_id = #{tenantId} AND workitem_id = #{workitemId} AND type = #{type}
ORDER BY id ASC

SELECT * FROM artifact
WHERE tenant_id = #{tenantId} AND dispatch_id = #{dispatchId}
ORDER BY id DESC

SELECT * FROM artifact
WHERE tenant_id = #{tenantId}
  AND (name = #{usageName} OR name LIKE CONCAT('%/', #{usageName}))
  AND dispatch_id IS NOT NULL
ORDER BY id ASC
LIMIT #{limit} OFFSET #{offset}
